export const PROJECT_STATUSES = ["active", "on_hold", "completed", "archived"] as const;
export type ProjectStatus = (typeof PROJECT_STATUSES)[number];

/** A client engagement container for Services Pro-style verticals (consultants, lawyers,
 *  coaches, artisans) — groups the TimeEntry/Task/Invoice rows already generated by an
 *  engagement so "how much time have we spent, how much have we billed, what's left" is one
 *  query instead of a manual cross-reference. Generic like every other capability added this
 *  session: any organization can create a Project, not just Services Pro ones. */
export interface Project {
  id: string;
  organizationId: string;
  contactId: string;
  name: string;
  description?: string;
  status: ProjectStatus;
  budgetHours?: number;
  budgetAmount?: number;
  currency?: string;
  startDate?: string;
  endDate?: string;
  createdAt: string;
  updatedAt: string;
}

export interface ProjectSummary {
  project: Project;
  totalHoursLogged: number;
  billableHoursLogged: number;
  totalBilled: number;
  openTaskCount: number;
  totalTaskCount: number;
}
